<script setup>
import { computed, nextTick, ref } from 'vue';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
import WaterAdjustmentSummary from './WaterAdjustmentSummary.vue';
import TaskMaterialCards from './TaskMaterialCards.vue';
import TaskOperationHighlights from './TaskOperationHighlights.vue';
import FermentationTrends from './FermentationTrends.vue';
const props=defineProps({detail:Object,initialStage:{type:String,default:''}});
const selected=ref(props.initialStage);
const detailSection=ref(null);
async function selectStage(id){
 selected.value=id;
 await nextTick();
 detailSection.value?.scrollIntoView({behavior:'smooth',block:'start'});
}
const materialState=computed(()=>props.detail.material_flow?.state || 'waiting_issue');
const materialSummary=computed(()=>({waiting_issue:'等待库管拣料发料',recommended:'已生成拣料清单，等待库管发料',issued:'已发到领料库，等待确认实领',acknowledged:'已确认实领',completed:'物料已结清'})[materialState.value] || '等待库管拣料发料');
const materialsReady=computed(()=>['acknowledged','completed'].includes(materialState.value));
const detailDialog=ref(''), selectedNode=ref(null);
const dialogTitle=computed(()=>({trends:'发酵测量趋势',tasks:'工艺任务与触发条件',records:'全部发酵记录',timeline:'全部流程时间线',node:selectedNode.value?.title || '糖化工序详情'})[detailDialog.value]);
function openNode(node){selectedNode.value=node;detailDialog.value='node';}

const plan=computed(()=>props.detail.plan);
const journey=computed(()=>props.detail.journey || {});
const tasks=computed(()=>props.detail.tasks || []);
const task=type=>tasks.value.find(t=>t.task_type===type&&t.state!=='cancelled');
const mash=computed(()=>task('mashing'));
const ferm=computed(()=>task('fermentation'));
const nodes=computed(()=>mash.value?.execution_checkpoints || []);
const execution=computed(()=>ferm.value?.fermentation_execution || {});
const records=computed(()=>[...(execution.value.records || [])].reverse());
const entries=computed(()=>execution.value.entries || []);
const packaging=computed(()=>plan.value.packaging_plan || {});
const orders=computed(()=>journey.value.packaging_orders || []);
const hasPackaging=computed(()=>!!(packaging.value.materials_only || packaging.value.material_id || packaging.value.packaging_id || orders.value.length));
const liquid=computed(()=>journey.value.liquid);
const completion=computed(()=>plan.value.brewing_completion || {});
const entered=computed(()=>nodes.value.find(n=>n.code==='transfer_fermenter'&&n.state==='done')?.completed_at || journey.value.batch?.entered_tank_at || execution.value.started_at);
const startMash=computed(()=>nodes.value.find(n=>n.code==='mash_in'&&n.state==='done')?.completed_at || mash.value?.started_at);
const endMash=computed(()=>mash.value?.completed_at);
const finished=computed(()=>plan.value.state==='done');
const names={draft:'草稿',checked:'已校验',stocking:'备料中',pending_approval:'待审批',approved:'待下发',dispatched:'已下发',in_progress:'执行中',done:'已完成',cancelled:'已取消',terminated:'已终止',in_tank:'已进罐',completed:'已完成',released:'已放行入库',pending_release:'待放行'};
const labels={temperature:'温度',gravity:'糖度',pressure:'压力',diacetyl:'双乙酰',attenuation:'实际发酵度'};
const units={temperature:'℃',gravity:'°P',pressure:'bar',diacetyl:'mg/L',attenuation:'%'};
const num=v=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3});
const date=v=>v?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未记录';
function duration(a,b){if(!a||!b)return '—';const minutes=Math.max(0,Math.round((Date.parse(/[zZ]|[+-]\d\d:\d\d$/.test(b)?b:b+'Z')-Date.parse(/[zZ]|[+-]\d\d:\d\d$/.test(a)?a:a+'Z'))/60000));return minutes>=60?`${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟`:`${minutes} 分钟`;}
const latest=computed(()=>{const values={};for(const r of [...records.value].sort((a,b)=>a.measured_at.localeCompare(b.measured_at))){for(const [key,value] of Object.entries(r.metrics||{}))values[key]={value,at:r.measured_at};}return values;});
const stages=computed(()=>[
 {id:'materials',name:'备料与下发',state:materialsReady.value?'done':plan.value.dispatched_at?'active':'waiting',summary:plan.value.dispatched_at?materialSummary.value:names[plan.value.state]||'待下发',at:plan.value.dispatched_at,owner:task('material_preparation')?.assignee?.name},
 {id:'mash',name:'糖化',state:mash.value?.state==='done'?'done':startMash.value?'active':'waiting',summary:`${nodes.value.filter(n=>n.state==='done').length} / ${nodes.value.length} 个工序已完成`,at:endMash.value||startMash.value,owner:mash.value?.assignee?.name},
 {id:'transfer',name:'冷却与进罐',state:entered.value?'done':'waiting',summary:entered.value?`已进 ${plan.value.tank?.name || '发酵罐'}`:'等待进罐',at:entered.value},
 {id:'fermentation',name:'发酵',state:ferm.value?.state==='done'?'done':execution.value.started_at?'active':'waiting',summary:ferm.value?.state==='done'?'发酵已结束':execution.value.started_at?`发酵第 ${execution.value.day} 天`:'尚未开始',at:execution.value.completion?.at||execution.value.started_at,owner:ferm.value?.assignee?.name},
 {id:'liquid',name:'原液与生产结果',state:finished.value?'done':entered.value?'active':'waiting',summary:liquid.value?`${finished.value?'原液待出酒':'在罐生产中'} · ${num(liquid.value.volume_l)} L`:completion.value.disposition==='emptied'?'原液已出酒 / 排空':entered.value?'在制余额为 0':'等待进罐',at:completion.value.completed_at||completion.value.confirmed_at},
 ...(hasPackaging.value?[{id:'packaging',name:'包装与成品入库（可选）',state:packaging.value.execution?.completed_at||orders.value.some(o=>o.state==='released')?'done':'waiting',summary:orders.value.some(o=>o.state==='released')?'已有成品入库':packaging.value.execution?.completed_at?'包装已记录':'待包装',at:packaging.value.execution?.completed_at}]:[])
]);
const activeStage=computed(()=>selected.value||stages.value.find(s=>s.state==='active')?.id||(finished.value?'liquid':'materials'));
</script>
<template>
<section class="production-journey">
 <div class="journey-intro"><div><small>生产全过程</small><h2>{{ plan.product?.name }} <span>{{ finished?'酿造已完成':plan.dispatched_at&&!materialsReady?materialSummary:names[plan.state] }}</span></h2><p>{{ journey.batch?.name || '生产批次尚未生成' }} · {{ plan.name }} · {{ plan.factory?.name }}</p></div><div class="journey-tank"><small>生产罐位</small><strong>{{ plan.tank?.name || '未分配' }}</strong></div></div>
 <div class="journey-metrics"><div><small>计划酒液量</small><strong>{{ num(plan.planned_volume_l) }} <em>L</em></strong></div><div><small>实际产酒量</small><strong>{{ num(completion.actual_volume_l ?? (journey.batch?.actual_volume_l>0?journey.batch.actual_volume_l:null)) }} <em>L</em></strong></div><div><small>当前在制原液</small><strong>{{ entered?num(liquid?.volume_l || 0):'—' }} <em>L</em></strong><small v-if="liquid?.volume_basis==='planned'">计划量估算，待录入实际量</small></div><div><small>当前阶段</small><strong class="journey-current">{{ finished?(hasPackaging?'酿造完成 · 包装另行跟进':'原液生产完成'):(plan.dispatched_at&&!materialsReady?materialSummary:stages.find(s=>s.state==='active')?.name || names[plan.state]) }}</strong><small v-if="!hasPackaging">本批次生产原液，无包装要求</small></div></div>
 <nav class="journey-stages" aria-label="生产阶段"><button v-for="(stage,index) in stages" :key="stage.id" type="button" :class="[stage.state,{selected:activeStage===stage.id}]" :aria-pressed="activeStage===stage.id" @click="selectStage(stage.id)"><i>{{ stage.state==='done'?'✓':index+1 }}</i><span><b>{{ stage.name }}</b><small>{{ stage.summary }}</small><time v-if="stage.at">{{ date(stage.at) }}</time><small v-if="stage.owner">负责人 {{ stage.owner }}</small></span><em>查看明细 ›</em></button></nav>
 <section ref="detailSection" class="journey-detail" style="scroll-margin-top:20px">
 <header><h3>{{ stages.find(s=>s.id===activeStage)?.name }}明细</h3><small>时间来自实际操作记录</small></header>
 <template v-if="activeStage==='materials'"><dl class="journey-facts"><div><dt>下发时间</dt><dd>{{ date(plan.dispatched_at) }}</dd></div><div><dt>领料状态</dt><dd>{{ materialSummary }}</dd></div></dl><article v-for="record in detail.material_requisitions" :key="record.id" class="journey-record"><strong>{{ record.name }}</strong><p>{{ names[record.state] || ({acknowledged:'已确认实领',issued:'已发料',recommended:'待发料'})[record.state] || '处理中' }}</p><div v-for="line in record.lines" :key="line.id"><b>{{ line.product?.name }}</b><p v-for="allocation in line.allocations" :key="allocation.id">批次 {{ allocation.lot?.name }} · 实领 {{ num(allocation.acknowledged_qty) }} {{ line.uom?.name }} · 耗用 {{ num(allocation.consumed_qty) }} · 退料 {{ num(allocation.returned_qty) }} · 损耗 {{ num(allocation.loss_qty) }}</p></div></article><p v-if="!detail.material_requisitions?.length" class="journey-empty">尚未生成领料记录。</p></template>
 <template v-if="activeStage==='mash'"><dl class="journey-facts"><div><dt>糖化投料 / 开始</dt><dd>{{ date(startMash) }}</dd></div><div><dt>糖化任务完成</dt><dd>{{ date(endMash) }}</dd></div><div><dt>实际过程时长</dt><dd>{{ duration(startMash,endMash) }}</dd></div><div><dt>负责人</dt><dd>{{ mash?.assignee?.name || '未分配' }}</dd></div></dl><div class="journey-table"><table><thead><tr><th>工序</th><th>状态 / 结果</th><th>确认时间</th><th>操作人</th><th>明细</th></tr></thead><tbody><tr v-for="node in nodes" :key="node.code"><td>{{ node.title }}</td><td><span :class="{success:node.state==='done'}">{{ node.state==='done'?'已完成':'待执行' }}</span><b v-if="node.value!==undefined && node.value!==null && node.value!==''"> · {{ node.value }} {{ node.unit }}</b><b v-if="node.actual_quantity!=null"> · 实际 {{ num(node.actual_quantity) }} {{ node.unit }}</b></td><td>{{ node.completed_at?date(node.completed_at):'—' }}</td><td>{{ node.completed_by || '—' }}</td><td><button type="button" class="journey-node-link" @click="openNode(node)">查看</button></td></tr></tbody></table></div><p v-if="!nodes.length" class="journey-empty">糖化尚未开始，暂无工序记录。</p></template>
 <template v-if="activeStage==='transfer'"><dl class="journey-facts"><div><dt>进罐完成时间</dt><dd>{{ date(entered) }}</dd></div><div><dt>发酵开始时间</dt><dd>{{ date(execution.started_at) }}</dd></div><div><dt>发酵罐</dt><dd>{{ plan.tank?.name || '未分配' }}</dd></div></dl><article v-for="node in nodes.filter(n=>['cooling_target','transfer_fermenter','actual_temperature','actual_gravity','actual_volume','pitch_yeast','yeast'].includes(n.code)||n.phase==='transfer')" :key="node.code" class="journey-record"><strong>{{ node.title }}</strong><p>{{ node.state==='done'?'已完成':'待执行' }}<template v-if="node.value!==undefined && node.value!==null && node.value!==''"> · {{ node.value }} {{ node.unit }}</template></p><small>{{ node.completed_at?date(node.completed_at):'尚未确认' }} · {{ node.completed_by || '未记录操作人' }}</small></article></template>
 <template v-if="activeStage==='fermentation'"><dl class="journey-facts"><div><dt>发酵状态</dt><dd>{{ ferm?.state==='done'?'已完成':execution.started_at?'发酵中':'未开始' }}</dd></div><div><dt>开始时间</dt><dd>{{ date(execution.started_at) }}</dd></div><div><dt>结束时间</dt><dd>{{ date(execution.completion?.at || ferm?.completed_at) }}</dd></div><div><dt>任务进度</dt><dd>{{ entries.filter(e=>e.status==='done').length }} / {{ entries.length }} 项<template v-if="execution.completion?.early"> · 提前结束，未完成项保留</template></dd></div></dl><h4>最新实测数据</h4><div class="journey-metrics"><div v-for="(metric,key) in latest" :key="key"><small>{{ labels[key] }}</small><strong>{{ num(metric.value) }} <em>{{ units[key] }}</em></strong><small>{{ date(metric.at) }}</small></div></div><p v-if="!records.length" class="journey-empty">尚未录入发酵测量数据。</p><button v-if="records.length" type="button" class="journey-detail-link" @click="detailDialog='trends'">查看测量趋势 <span>›</span></button><button type="button" class="journey-detail-link" @click="detailDialog='tasks'">工艺任务与触发条件 <small>{{ entries.filter(e=>e.status==='done').length }} / {{ entries.length }} 已完成</small><span>›</span></button><button type="button" class="journey-detail-link" @click="detailDialog='records'">查看全部发酵记录 <small>{{ records.length }} 条</small><span>›</span></button></template>
 <template v-if="activeStage==='liquid'"><div class="journey-result"><strong>{{ ['cancelled','terminated'].includes(plan.state)?names[plan.state]:finished?'原液酿造已完成':'原液生产中' }}</strong><p>{{ !hasPackaging?'本批次无需包装任务；酿造完成后即可作为原液跟踪。':'包装为后续独立流程，不影响酿造完成状态。' }}</p></div><dl class="journey-facts"><div><dt>生产完成时间</dt><dd>{{ date(completion.completed_at || completion.confirmed_at || journey.batch?.completed_at) }}</dd></div><div><dt>完成确认人</dt><dd>{{ completion.completed_by || completion.confirmed_by || '尚未记录' }}</dd></div><div><dt>当前原液量</dt><dd>{{ entered?num(liquid?.volume_l || 0):'—' }} L <small v-if="liquid?.volume_basis==='planned'">（计划量估算）</small></dd></div><div><dt>原液状态</dt><dd>{{ completion.disposition==='emptied'?'已出酒 / 排空':liquid?'原液在罐':entered?'无剩余在制量':'尚未进罐' }}</dd></div><div><dt>罐位 / 去向</dt><dd>{{ completion.destination || plan.tank?.name || '未记录' }}</dd></div><div><dt>已包装 / 包装损耗</dt><dd>{{ num(liquid?.packaged_volume_l ?? (orders.reduce((s,o)=>s+o.volume_l,0)+(packaging.execution?.output_volume_l||0))) }} L / {{ num(liquid?.packaging_loss_l ?? (orders.reduce((s,o)=>s+o.loss_l,0)+(packaging.execution?.loss_volume_l||0))) }} L</dd></div></dl><p class="journey-empty">在制原液量与酒厂库存同步统计，原液不计入可销售成品库存。</p></template>
 <template v-if="activeStage==='packaging'"><p class="journey-empty">包装为可选后续流程，单独记录包装产出、损耗和成品入库。</p><article v-if="packaging.execution" class="journey-record"><strong>包装任务记录</strong><p>{{ date(packaging.execution.completed_at) }} · {{ packaging.execution.completed_by }}</p><p v-if="!packaging.materials_only">包装产出 {{ num(packaging.execution.output_volume_l) }} L · 损耗 {{ num(packaging.execution.loss_volume_l) }} L</p><p v-else>已完成包装材料使用登记</p><p>{{ packaging.execution.notes }}</p></article><article v-for="order in orders" :key="order.id" class="journey-record"><strong>{{ order.name }} · {{ names[order.state] || '待包装' }}</strong><p>{{ order.specification }} · 产出 {{ num(order.volume_l) }} L · 损耗 {{ num(order.loss_l) }} L</p><p>成品批次 {{ order.lot || '尚未生成' }} · 入库时间 {{ date(order.released_at) }}</p><p>{{ order.location }} · 当前库存 {{ num(order.on_hand) }} {{ order.unit }} · 可用 {{ num(order.available) }} {{ order.unit }}</p></article><p v-if="!orders.length" class="journey-empty">尚无成品入库记录。包装任务完成记录不等同于成品已入库。</p></template>
 </section>
 <button type="button" class="journey-detail-link journey-timeline-link" @click="detailDialog='timeline'">全部流程时间线 <small>{{ detail.timeline?.length || 0 }} 条</small><span>›</span></button>
 <JourneyDetailDialog v-if="detailDialog" :title="dialogTitle" :subtitle="`${plan.product?.name || ''} · ${journey.batch?.name || plan.name}`" @close="detailDialog=''">
 <template v-if="detailDialog==='trends'"><FermentationTrends :records="records" :labels="labels" :units="units" /></template>
 <template v-else-if="detailDialog==='tasks'"><article v-for="entry in entries" :key="entry.id" class="journey-record"><strong>{{ entry.action_label }} {{ entry.rule.target || '' }}</strong><span class="journey-state">{{ ({done:'已完成',pending:'待执行',overdue:'待补录',future:'未到日期',waiting:'等待条件'})[entry.status] || '待执行' }}</span><p>{{ entry.day?`发酵第 ${entry.day} 天 · ${entry.date}`:`${labels[entry.rule.condition] || '条件'} ${entry.rule.operator} ${entry.rule.condition_value} ${units[entry.rule.condition] || ''}` }}</p></article><p v-if="!entries.length" class="journey-empty">暂无发酵工艺任务。</p></template>
 <template v-else-if="detailDialog==='records'"><article v-for="record in records" :key="record.id" class="journey-record"><strong>{{ date(record.measured_at) }} · {{ record.by }}</strong><p>{{ Object.entries(record.metrics || {}).map(([k,v])=>`${labels[k]} ${num(v)} ${units[k]}`).join(' · ') }}</p><p>{{ (record.entry_ids || []).map(id=>entries.find(e=>e.id===id)?.action_label).filter(Boolean).join('、') }}</p><p v-if="record.note">{{ record.note }}</p></article><p v-if="!records.length" class="journey-empty">暂无发酵记录。</p></template>
 <template v-else-if="detailDialog==='timeline'"><article v-for="(event,index) in detail.timeline" :key="index" class="journey-record"><strong>{{ event.title }}</strong><p>{{ date(event.at) }} · {{ event.by || '系统记录' }}<template v-if="event.value!==undefined && event.value!==''"> · {{ event.value }}</template></p></article></template>
 <template v-else-if="detailDialog==='node' && selectedNode"><dl class="journey-facts"><div><dt>执行状态</dt><dd :class="{success:selectedNode.state==='done'}">{{ selectedNode.state==='done'?'已完成':'待执行' }}</dd></div><div><dt>操作人</dt><dd>{{ selectedNode.completed_by || '尚未记录' }}</dd></div><div><dt>确认时间</dt><dd>{{ selectedNode.completed_at?date(selectedNode.completed_at):'尚未记录' }}</dd></div><div v-if="selectedNode.value!==undefined && selectedNode.value!==null && selectedNode.value!==''"><dt>操作结果</dt><dd>{{ selectedNode.value }} {{ selectedNode.unit }}</dd></div><div v-if="selectedNode.actual_quantity!=null"><dt>实际用量</dt><dd>{{ num(selectedNode.actual_quantity) }} {{ selectedNode.unit }}</dd></div></dl><WaterAdjustmentSummary v-if="selectedNode.water_adjustment" :snapshot="selectedNode.water_adjustment" :actual="selectedNode.water_actual" /><TaskMaterialCards :materials="selectedNode.execution_details?.materials || []" /><TaskOperationHighlights :items="selectedNode.execution_details?.requirements || []" label="工艺要求" /><p v-if="selectedNode.target" class="journey-empty">{{ selectedNode.target }}</p><article v-if="selectedNode.actual_note" class="journey-record"><strong>实际操作说明</strong><p>{{ selectedNode.actual_note }}</p></article></template>
 </JourneyDetailDialog>

</section>
</template>
<style scoped>
.production-journey{color:var(--text-primary)}.journey-intro{display:flex;justify-content:space-between;gap:24px;margin:4px 0 24px}.journey-intro small{color:#d4b36b;font-size:12px}.journey-intro h2{font-size:24px;margin:10px 0}.journey-intro h2 span{display:inline-block;font-size:12px;font-weight:500;color:#b9d2ab;background:#91bc9118;border-radius:5px;padding:5px 9px;margin-left:12px;vertical-align:middle}.journey-intro p{color:var(--text-muted);font-size:12px;line-height:1.8;margin:0}.journey-tank{text-align:right}.journey-tank strong{display:block;font-size:26px;margin-top:10px;font-weight:500}.journey-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0 26px}.journey-metrics>div{padding:18px;background:#ffffff03;border:1px solid var(--border-default);border-radius:10px}.journey-metrics small{display:block;font-size:11px;color:var(--text-muted);line-height:1.8}.journey-metrics strong{display:block;font-size:25px;color:#e0bc70;margin:8px 0;font-weight:550}.journey-metrics em{font-style:normal;font-size:13px;color:var(--text-secondary)}.journey-metrics strong.journey-current{font-size:16px;line-height:1.6}.journey-stages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:28px}.journey-stages button{position:relative;display:flex;align-items:flex-start;gap:12px;padding:18px 15px 32px;text-align:left;background:#ffffff02;border:1px solid var(--border-default);border-radius:10px;color:inherit;font:inherit;cursor:pointer}.journey-stages button.selected{border-color:#d4a85390;background:#d4a8530b}.journey-stages i{display:grid;place-items:center;flex-shrink:0;width:26px;height:26px;border:1px solid #ffffff25;border-radius:50%;font-size:12px;font-style:normal;color:var(--text-muted)}.journey-stages .done i{border-color:#91bc9160;color:#b5d3a6;background:#91bc9112}.journey-stages .active i{border-color:#d4a85390;color:#e0bc70}.journey-stages b{display:block;font-size:13px;line-height:1.7}.journey-stages 